import Foundation
import SwiftUI

enum AppLanguage: String, CaseIterable, Identifiable {
    case english = "en"
    case thai = "th"
    case chinese = "zh"
    case japanese = "ja"
    case korean = "ko"
    case spanish = "es"
    case french = "fr"
    case german = "de"
    case portuguese = "pt"
    case arabic = "ar"
    case italian = "it"
    case russian = "ru"

    var id: String { rawValue }

    var displayName: String {
        switch self {
        case .english: return "English"
        case .thai: return "ไทย"
        case .chinese: return "中文"
        case .japanese: return "日本語"
        case .korean: return "한국어"
        case .spanish: return "Español"
        case .french: return "Français"
        case .german: return "Deutsch"
        case .portuguese: return "Português"
        case .arabic: return "العربية"
        case .italian: return "Italiano"
        case .russian: return "Русский"
        }
    }

    var flag: String {
        switch self {
        case .english: return "🇺🇸"
        case .thai: return "🇹🇭"
        case .chinese: return "🇨🇳"
        case .japanese: return "🇯🇵"
        case .korean: return "🇰🇷"
        case .spanish: return "🇪🇸"
        case .french: return "🇫🇷"
        case .german: return "🇩🇪"
        case .portuguese: return "🇧🇷"
        case .arabic: return "🇸🇦"
        case .italian: return "🇮🇹"
        case .russian: return "🇷🇺"
        }
    }
}

@MainActor
class LocalizationManager: ObservableObject {
    @AppStorage("appLanguage") var currentLanguage: AppLanguage = .english

    func t(_ key: String) -> String {
        return Translations.get(key, language: currentLanguage)
    }
}

enum Translations {
    static func get(_ key: String, language: AppLanguage) -> String {
        let dict: [String: String]
        switch language {
        case .english: dict = english
        case .thai: dict = thai
        case .chinese: dict = chinese
        case .japanese: dict = japanese
        case .korean: dict = korean
        case .spanish: dict = spanish
        case .french: dict = french
        case .german: dict = german
        case .portuguese: dict = portuguese
        case .arabic: dict = arabic
        case .italian: dict = italian
        case .russian: dict = russian
        }
        // `extras` holds newer keys (Show-Off Mode, logging master switch, etc.)
        // kept separate from the large per-language tables for maintainability.
        // Resolution order: language extras → language table → English extras →
        // English table → raw key.
        if let value = showOffVariantExtras[language]?[key] { return value }
        if let value = showOffExtras[language]?[key] { return value }
        if let value = extras[language]?[key] { return value }
        if let value = dict[key] { return value }
        if let value = showOffVariantExtras[.english]?[key] { return value }
        if let value = showOffExtras[.english]?[key] { return value }
        if let value = extras[.english]?[key] { return value }
        if let value = english[key] { return value }
        return key
    }

    static func showOffVariantKey(for text: String) -> String {
        let scalars = text.unicodeScalars.map { scalar -> Character in
            if CharacterSet.alphanumerics.contains(scalar) {
                return Character(scalar)
            }
            return "-"
        }
        return "showoff.variant." + String(scalars)
            .lowercased()
            .split(separator: "-")
            .joined(separator: "-")
    }

    /// Supplementary translation tables, merged ahead of the main per-language
    /// dictionaries. Add new UI strings here so every language stays in sync in
    /// one place. Missing keys fall back to the English entry, then the raw key.
