    private static func showOffTable(_ entries: [(id: String, title: String, short: String, variants: [String])]) -> [String: String] {
        var table: [String: String] = [:]
        for entry in entries {
            table["showoff.sensor.\(entry.id).title"] = entry.title
            table["showoff.sensor.\(entry.id).short"] = entry.short
            for (index, variant) in entry.variants.enumerated() {
                table["showoff.sensor.\(entry.id).variant.\(index)"] = variant
            }
        }
        return table
    }

    private static func showOffVariantTable(_ entries: [(source: String, value: String)]) -> [String: String] {
        var table: [String: String] = [:]
        for entry in entries {
            table[showOffVariantKey(for: entry.source)] = entry.value
        }
        return table
    }

